INSERT INTO stories (id,location_id,title,summary,simplified_story,audience,language,tone,source,is_ai_generated,status,uncertainty_notes) VALUES ('record-palestinian-museum','palestinian-museum','The Palestinian Museum','A cultural institution in Birzeit beside Birzeit University, documenting Palestinian history and culture.','A cultural institution in Birzeit beside Birzeit University, documenting Palestinian history and culture. The museum''s first building phase was completed in 2016. Its terraced design draws on the surrounding landscape.','general','en','neutral','content/ai-ready/palestinian-museum-summary.md',FALSE,'published',ARRAY['This record contains source-checked factual summaries and credited, licensed photographs; each photograph shows its date and source. Local oral accounts and current access information have not been added. Coordinates, when available, are reference points, not entrances. This is a cultural reading journey; it does not establish a physical route, travel time, accessibility or permission to visit.']::text[]) ON CONFLICT DO NOTHING;
