INSERT INTO quiz_questions (id,location_id,question,options,answer_index,explanation,source_note,sort_order) VALUES ('palestine-quiz-palestinian-museum','palestinian-museum','In which town is the Palestinian Museum?',ARRAY['Birzeit','Hebron','Gaza']::text[],0,'A cultural institution in Birzeit beside Birzeit University, documenting Palestinian history and culture. The museum''s first building phase was completed in 2016. Its terraced design draws on the surrounding landscape. ','https://palmuseum.org/en/node/3720',0) ON CONFLICT DO NOTHING;
INSERT INTO locations (id,governorate_id,name,arabic_name,city,country,latitude,longitude,description,arabic_description,content_file,ai_summary_file,is_published,review_status,coordinate_status) VALUES ('yasser-arafat-museum','ramallah','Yasser Arafat Museum','متحف ياسر عرفات','Ramallah','Palestine',NULL,NULL,'The Yasser Arafat Museum at Al-Muqata''a in Ramallah presents contemporary Palestinian national memory through Arafat''s life and the Palestinian national movement. It is connected to the historic compound associated with his headquarters, office and residence, and overlooks his temporary mausoleum and the square where Palestinians gathered for his farewell.','يقع متحف ياسر عرفات في المقاطعة برام الله، ويعرض الذاكرة الوطنية الفلسطينية المعاصرة من خلال سيرة عرفات والحركة الوطنية الفلسطينية. يرتبط المتحف بالمبنى التاريخي الذي ضم مقر القيادة والمكتب والإقامة، ويطل على ضريحه المؤقت وساحة المقاطعة التي شهدت وداعه.','content/ai-ready/yasser-arafat-museum-summary.md','content/ai-ready/yasser-arafat-museum-summary.md',TRUE,'source_checked','pending_verification') ON CONFLICT DO NOTHING;
