INSERT INTO stories (id,location_id,title,summary,simplified_story,audience,language,tone,source,is_ai_generated,status,uncertainty_notes) VALUES ('record-yasser-arafat-museum','yasser-arafat-museum','Yasser Arafat Museum','The Yasser Arafat Museum at Al-Muqata''a in Ramallah presents contemporary Palestinian national memory through Arafat''s life and the Palestinian national movement. It is connected to the historic compound associated with his headquarters, office and residence, and overlooks his temporary mausoleum and the square where Palestinians gathered for his farewell.','The Yasser Arafat Museum at Al-Muqata''a in Ramallah presents contemporary Palestinian national memory through Arafat''s life and the Palestinian national movement. It is connected to the historic compound associated with his headquarters, office and residence, and overlooks his temporary mausoleum and the square where Palestinians gathered for his farewell. Designed by Palestinian architect Ja''far Touqan, the museum stands on a 1,350-square-metre plot and has about 2,600 square metres of built area, according to the museum. Four ascending ramps form the main exhibition route, followed by a bridge to the historic Muqata''a building. The museum says the preserved headquarters area is presented as it was when Arafat left after a 34-month siege. Its Resource Centre includes a specialized library and a bilingual Arabic-English electronic archive covering Arafat and Palestinian history from the early twentieth century through 2004. The site also describes a 100-seat forum theatre and a rotating exhibition hall.','general','en','neutral','content/ai-ready/yasser-arafat-museum-summary.md',FALSE,'published',ARRAY['This record does not verify current opening hours, site condition, entrance details, or present access; it therefore cannot establish that a visit or a particular route is currently possible.']::text[]) ON CONFLICT DO NOTHING;
INSERT INTO media (id,location_id,type,url,thumb_url,width,height,subject,subject_ar,description,description_ar,era,pair_role,credit,license,license_url,captured_at,source_url,sort_order) VALUES ('yasser-arafat-museum-01','yasser-arafat-museum','image','https://commons.wikimedia.org/wiki/Special:FilePath/Yasser_Arafat_Museum002.jpg?width=1600','https://commons.wikimedia.org/wiki/Special:FilePath/Yasser_Arafat_Museum002.jpg?width=600',8000,6000,'Exhibition gallery','قاعة العرض','Visitors in one of the museum’s exhibition galleries, 2021.','زوار في إحدى قاعات العرض في المتحف، 2021.','modern','cover','Talmoryair','CC BY-SA 4.0','https://creativecommons.org/licenses/by-sa/4.0','2021-10-28','https://commons.wikimedia.org/wiki/File:Yasser_Arafat_Museum002.jpg',0) ON CONFLICT DO NOTHING;
INSERT INTO media (id,location_id,type,url,thumb_url,width,height,subject,subject_ar,description,description_ar,era,pair_role,credit,license,license_url,captured_at,source_url,sort_order) VALUES ('yasser-arafat-museum-02','yasser-arafat-museum','image','https://commons.wikimedia.org/wiki/Special:FilePath/Yasser_Arafat_Museum006.jpg?width=1600','https://commons.wikimedia.org/wiki/Special:FilePath/Yasser_Arafat_Museum006.jpg?width=600',3000,3000,'Nobel Peace Prize diploma','شهادة جائزة نوبل للسلام','A Nobel Peace Prize diploma displayed in a museum case, 2021.','شهادة جائزة نوبل للسلام معروضة في واجهة داخل المتحف، 2021.','modern',NULL,'Talmoryair','CC BY-SA 4.0','https://creativecommons.org/licenses/by-sa/4.0','2021-10-28','https://commons.wikimedia.org/wiki/File:Yasser_Arafat_Museum006.jpg',1) ON CONFLICT DO NOTHING;
INSERT INTO media (id,location_id,type,url,thumb_url,width,height,subject,subject_ar,description,description_ar,era,pair_role,credit,license,license_url,captured_at,source_url,sort_order) VALUES ('yasser-arafat-museum-03','yasser-arafat-museum','image','https://commons.wikimedia.org/wiki/Special:FilePath/Yasser_Arafat_Museum003.jpg?width=1600','https://commons.wikimedia.org/wiki/Special:FilePath/Yasser_Arafat_Museum003.jpg?width=600',3000,3000,'Office on display','مكتب معروض','An office shown in the museum, with a picture of the Dome of the Rock behind the desk, 2021.','مكتب معروض في المتحف، وخلف المكتب صورة لقبة الصخرة، 2021.','modern',NULL,'Talmoryair','CC BY-SA 4.0','https://creativecommons.org/licenses/by-sa/4.0','2021-10-28','https://commons.wikimedia.org/wiki/File:Yasser_Arafat_Museum003.jpg',2) ON CONFLICT DO NOTHING;
INSERT INTO quiz_questions (id,location_id,question,options,answer_index,explanation,source_note,sort_order) VALUES ('palestine-quiz-yasser-arafat-museum','yasser-arafat-museum','Which place houses this museum?',ARRAY['Al-Muqata''a, Ramallah','Jerusalem''s Old City','Gaza harbour']::text[],0,'The Yasser Arafat Museum at Al-Muqata''a in Ramallah presents contemporary Palestinian national memory through Arafat''s life and the Palestinian national movement. It is connected to the historic compound associated with his headquarters, office and residence, and overlooks his temporary mausoleum and the square where Palestinians gathered for his farewell. Designed by Palestinian architect Ja''far Touqan, the museum stands on a 1,350-square-metre plot and has about 2,600 square metres of built area, according to the museum. Four ascending ramps form the main exhibition route, followed by a bridge to the historic Muqata''a building. The museum says the preserved headquarters area is presented as it was when Arafat left after a 34-month siege. Its Resource Centre includes a specialized library and a bilingual Arabic-English electronic archive covering Arafat and Palestinian history from the early twentieth century through 2004. The site also describes a 100-seat forum theatre and a rotating exhibition hall. ','https://www.yam.ps/',0) ON CONFLICT DO NOTHING;
INSERT INTO locations (id,governorate_id,name,arabic_name,city,country,latitude,longitude,description,arabic_description,content_file,ai_summary_file,is_published,review_status,coordinate_status) VALUES ('throne-villages','ramallah','Throne Villages: Ras Karkar and Deir Ghassaneh','قرى الكراسي: راس كركر ودير غسانة','Ras Karkar','Palestine',31.942979,35.102654,'Hilltop seats of the sheikhs who ruled the central highlands in the 18th and 19th centuries, where fortified mansions rise above the village houses.','مقارّ المشايخ الذين حكموا المرتفعات الوسطى في القرنين الثامن عشر والتاسع عشر، حيث ترتفع القصور المحصّنة فوق بيوت القرية على رؤوس التلال.','content/ai-ready/throne-villages-summary.md','content/ai-ready/throne-villages-summary.md',TRUE,'source_checked','unesco_tentative_list_reference') ON CONFLICT DO NOTHING;
