INSERT INTO stories (id,location_id,title,summary,simplified_story,audience,language,tone,source,is_ai_generated,status,uncertainty_notes) VALUES ('record-throne-villages','throne-villages','Throne Villages: Ras Karkar and Deir Ghassaneh','Hilltop seats of the sheikhs who ruled the central highlands in the 18th and 19th centuries, where fortified mansions rise above the village houses.','Hilltop seats of the sheikhs who ruled the central highlands in the 18th and 19th centuries, where fortified mansions rise above the village houses. In the 18th and 19th centuries the central highlands were divided into twenty-four sheikhdoms. Each sheikh collected taxes for the Ottoman government, and the villages where the sheikhs and their clans lived were called “throne villages”. Ras Karkar and Deir Ghassaneh are two of the thirteen villages named in Palestine’s tentative-list entry.','general','en','neutral','content/ai-ready/throne-villages-summary.md',FALSE,'published',ARRAY['The map point marks Ras Karkar as listed by UNESCO; Deir Ghassaneh lies further north and is not mapped separately. Current access and the condition of individual buildings are not asserted.']::text[]) ON CONFLICT DO NOTHING;
INSERT INTO timeline_events (id,location_id,period_label,description,sort_year,sort_order,is_tradition,source_file) VALUES ('palestine-timeline-throne-villages-0','throne-villages','18th–19th centuries','The central highlands are divided into twenty-four sheikhdoms ruled from the throne villages.',1700,0,FALSE,'content/ai-ready/throne-villages-summary.md') ON CONFLICT DO NOTHING;
