INSERT INTO quiz_questions (id,location_id,question,options,answer_index,explanation,source_note,sort_order) VALUES ('palestine-quiz-throne-villages','throne-villages','Who lived in the “throne villages”?',ARRAY['Byzantine monks','Local sheikhs and their clans','Roman governors']::text[],1,'Hilltop seats of the sheikhs who ruled the central highlands in the 18th and 19th centuries, where fortified mansions rise above the village houses. In the 18th and 19th centuries the central highlands were divided into twenty-four sheikhdoms. Each sheikh collected taxes for the Ottoman government, and the villages where the sheikhs and their clans lived were called “throne villages”. Ras Karkar and Deir Ghassaneh are two of the thirteen villages named in Palestine’s tentative-list entry. ','https://whc.unesco.org/en/tentativelists/5717/',0) ON CONFLICT DO NOTHING;
INSERT INTO locations (id,governorate_id,name,arabic_name,city,country,latitude,longitude,description,arabic_description,content_file,ai_summary_file,is_published,review_status,coordinate_status) VALUES ('nablus-old-city','nablus','Historic City of Nablus','البلدة القديمة في نابلس','Nablus','Palestine',32.219278,35.260306,'A dense Roman–Islamic old city between Mount Ebal and Mount Gerizim, with six main quarters, covered markets, bathhouses and the soap factories behind Nabulsi soap.','بلدة قديمة رومانية إسلامية متلاصقة البناء بين جبلَي عيبال وجرزيم، فيها ست حارات رئيسية وأسواق مسقوفة وحمّامات ومصابن الصابون النابلسي.','content/ai-ready/nablus-old-city-summary.md','content/ai-ready/nablus-old-city-summary.md',TRUE,'source_checked','unesco_tentative_list_reference') ON CONFLICT DO NOTHING;
