INSERT INTO stories (id,location_id,title,summary,simplified_story,audience,language,tone,source,is_ai_generated,status,uncertainty_notes) VALUES ('record-nablus-old-city','nablus-old-city','Historic City of Nablus','A dense Roman–Islamic old city between Mount Ebal and Mount Gerizim, with six main quarters, covered markets, bathhouses and the soap factories behind Nabulsi soap.','A dense Roman–Islamic old city between Mount Ebal and Mount Gerizim, with six main quarters, covered markets, bathhouses and the soap factories behind Nabulsi soap. Nablus stands on the Roman city of Flavia Neapolis, founded under Vespasian in 72 AD, and its two main streets still follow the Roman Decumanus and Cardo. The Ottoman Clock Tower in Bab al-Saha square was built in 1898. By 1882 the city had 30 soap factories, and Nabulsi soap-making was inscribed on UNESCO’s Intangible Cultural Heritage list in December 2024.','general','en','neutral','content/ai-ready/nablus-old-city-summary.md',FALSE,'published',ARRAY['This record contains source-checked factual summaries and credited, licensed photographs; each photograph shows its date and source. Local oral accounts and current access information have not been added. Coordinates, when available, are reference points, not entrances. This is a cultural reading journey; it does not establish a physical route, travel time, accessibility or permission to visit.']::text[]) ON CONFLICT DO NOTHING;
