INSERT INTO media (id,location_id,type,url,thumb_url,width,height,subject,subject_ar,description,description_ar,era,pair_role,credit,license,license_url,captured_at,source_url,sort_order) VALUES ('nablus-old-city-05','nablus-old-city','image','https://commons.wikimedia.org/wiki/Special:FilePath/Arab_factories_%26_gen%28eral%29_improvements_in_Nablus._The_new_mosque._Int%28erior%29_from_main_doorway._East_entr%28ance%29_LOC_matpc.04374.jpg?width=1600','https://commons.wikimedia.org/wiki/Special:FilePath/Arab_factories_%26_gen%28eral%29_improvements_in_Nablus._The_new_mosque._Int%28erior%29_from_main_doorway._East_entr%28ance%29_LOC_matpc.04374.jpg?width=600',5747,4279,'An-Nasr Mosque prayer hall','قاعة الصلاة في جامع النصر','The prayer hall in 1940, when the Matson caption called it “the new mosque”: arched windows, mihrab and minbar.','قاعة الصلاة عام 1940، حين سمّاها تعليق مجموعة ماتسون «الجامع الجديد»: نوافذ معقودة ومحراب ومنبر.','historical','before','Matson Collection, Library of Congress','Public domain','https://creativecommons.org/publicdomain/mark/1.0/','1940','https://commons.wikimedia.org/wiki/File:Arab_factories_%26_gen(eral)_improvements_in_Nablus._The_new_mosque._Int(erior)_from_main_doorway._East_entr(ance)_LOC_matpc.04374.jpg',4) ON CONFLICT DO NOTHING;
