INSERT INTO quiz_questions (id,location_id,question,options,answer_index,explanation,source_note,sort_order) VALUES ('palestine-quiz-nablus-old-city','nablus-old-city','Which Nablus craft was inscribed on UNESCO’s Intangible Cultural Heritage list in 2024?',ARRAY['Glass-blowing','Mother-of-pearl carving','Nabulsi soap-making']::text[],2,'A dense Roman–Islamic old city between Mount Ebal and Mount Gerizim, with six main quarters, covered markets, bathhouses and the soap factories behind Nabulsi soap. Nablus stands on the Roman city of Flavia Neapolis, founded under Vespasian in 72 AD, and its two main streets still follow the Roman Decumanus and Cardo. The Ottoman Clock Tower in Bab al-Saha square was built in 1898. By 1882 the city had 30 soap factories, and Nabulsi soap-making was inscribed on UNESCO’s Intangible Cultural Heritage list in December 2024. ','https://whc.unesco.org/en/tentativelists/6956/',0) ON CONFLICT DO NOTHING;
INSERT INTO locations (id,governorate_id,name,arabic_name,city,country,latitude,longitude,description,arabic_description,content_file,ai_summary_file,is_published,review_status,coordinate_status) VALUES ('sebastia','nablus','Sebastia','سبسطية','Sebastia','Palestine',32.276339,35.188875,'A multi-period hill site north-west of Nablus whose layers run from the Iron Age city widely identified with ancient Samaria, through Roman Sebaste, to Byzantine, Crusader and Ottoman remains.','موقع متعدد الحقب على تلّ شمال غرب نابلس، تمتد طبقاته من مدينة العصر الحديدي التي تُعرَّف على نطاق واسع بالسامرة القديمة، مروراً بسبسطية الرومانية، إلى بقايا بيزنطية وصليبية وعثمانية.','content/ai-ready/sebastia-summary.md','content/ai-ready/sebastia-summary.md',TRUE,'source_checked','unesco_property_reference') ON CONFLICT DO NOTHING;
