INSERT INTO stories (id,location_id,title,summary,simplified_story,audience,language,tone,source,is_ai_generated,status,uncertainty_notes) VALUES ('record-sebastia','sebastia','Sebastia','A multi-period hill site north-west of Nablus whose layers run from the Iron Age city widely identified with ancient Samaria, through Roman Sebaste, to Byzantine, Crusader and Ottoman remains.','A multi-period hill site north-west of Nablus whose layers run from the Iron Age city widely identified with ancient Samaria, through Roman Sebaste, to Byzantine, Crusader and Ottoman remains. Occupation here is documented from the 9th century BCE. The city was a fortified stronghold in the Hellenistic period, was renamed Sebaste by Herod and became a Roman colony under Septimius Severus; in the Byzantine period it was the seat of a bishopric. UNESCO inscribed Sebastia on the World Heritage List in 2026 and placed it on the List of World Heritage in Danger the same year; its statement names land expropriation plans aimed at dividing the property among the threats to its integrity.','general','en','neutral','content/ai-ready/sebastia-summary.md',FALSE,'published',ARRAY['This record contains source-checked factual summaries and credited, licensed photographs; each photograph shows its date and source. Local oral accounts and current access information have not been added. Coordinates, when available, are reference points, not entrances. This is a cultural reading journey; it does not establish a physical route, travel time, accessibility or permission to visit.']::text[]) ON CONFLICT DO NOTHING;
