INSERT INTO quiz_questions (id,location_id,question,options,answer_index,explanation,source_note,sort_order) VALUES ('palestine-quiz-sebastia','sebastia','What name did Herod give to the city?',ARRAY['Neapolis','Sebaste','Anthedon']::text[],1,'A multi-period hill site north-west of Nablus whose layers run from the Iron Age city widely identified with ancient Samaria, through Roman Sebaste, to Byzantine, Crusader and Ottoman remains. Occupation here is documented from the 9th century BCE. The city was a fortified stronghold in the Hellenistic period, was renamed Sebaste by Herod and became a Roman colony under Septimius Severus; in the Byzantine period it was the seat of a bishopric. UNESCO inscribed Sebastia on the World Heritage List in 2026 and placed it on the List of World Heritage in Danger the same year; its statement names land expropriation plans aimed at dividing the property among the threats to its integrity. ','https://whc.unesco.org/en/list/1809/',0) ON CONFLICT DO NOTHING;
