INSERT INTO stories (id,location_id,title,summary,simplified_story,audience,language,tone,source,is_ai_generated,status,uncertainty_notes) VALUES ('record-mount-gerizim','mount-gerizim','Mount Gerizim and the Samaritans','The sacred mountain of the Samaritans above Nablus, whose summit holds a Hellenistic town, a Byzantine church and a later Muslim shrine.','The sacred mountain of the Samaritans above Nablus, whose summit holds a Hellenistic town, a Byzantine church and a later Muslim shrine. The temple found on the summit existed before the later 2nd century BC; the town around it was probably destroyed by John Hyrcanus in 128 BC. In 484 AD an octagonal church dedicated to Mary Theotokos was built on the summit and later fortified under Justinian. In the 16th century a shrine of the Muslim saint Sheikh Ghanim was built on a corner of the ruined church.','general','en','neutral','content/ai-ready/mount-gerizim-summary.md',FALSE,'published',ARRAY['This record contains source-checked factual summaries and credited, licensed photographs; each photograph shows its date and source. Local oral accounts and current access information have not been added. Coordinates, when available, are reference points, not entrances. This is a cultural reading journey; it does not establish a physical route, travel time, accessibility or permission to visit.']::text[]) ON CONFLICT DO NOTHING;
