INSERT INTO quiz_questions (id,location_id,question,options,answer_index,explanation,source_note,sort_order) VALUES ('palestine-quiz-mount-gerizim','mount-gerizim','Which community regards Mount Gerizim as its sacred mountain?',ARRAY['The Armenians','The Copts','The Samaritans']::text[],2,'The sacred mountain of the Samaritans above Nablus, whose summit holds a Hellenistic town, a Byzantine church and a later Muslim shrine. The temple found on the summit existed before the later 2nd century BC; the town around it was probably destroyed by John Hyrcanus in 128 BC. In 484 AD an octagonal church dedicated to Mary Theotokos was built on the summit and later fortified under Justinian. In the 16th century a shrine of the Muslim saint Sheikh Ghanim was built on a corner of the ruined church. In Samaritan belief, Mount Gerizim is the mountain of the Blessing and the site of the first temple in the Holy Land, built by Yosha’ bin Noun; Samaritans also believe that a rock on the summit is where Abraham was about to sacrifice his son Isaac.','https://whc.unesco.org/en/tentativelists/5706/',0) ON CONFLICT DO NOTHING;
INSERT INTO locations (id,governorate_id,name,arabic_name,city,country,latitude,longitude,description,arabic_description,content_file,ai_summary_file,is_published,review_status,coordinate_status) VALUES ('tell-es-sultan','jericho','Ancient Jericho / Tell es-Sultan','أريحا القديمة / تل السلطان','Jericho','Palestine',31.871306,35.444056,'An oval mound north-west of present-day Jericho holding traces of human activity from about 10,500 BC, beside the perennial spring of ‘Ain es-Sultan.','تلّ بيضاوي شمال غرب أريحا الحالية يحفظ آثار نشاط بشري منذ نحو 10,500 قبل الميلاد، بجوار نبع عين السلطان الدائم.','content/ai-ready/tell-es-sultan-summary.md','content/ai-ready/tell-es-sultan-summary.md',TRUE,'source_checked','unesco_property_reference') ON CONFLICT DO NOTHING;
