INSERT INTO stories (id,location_id,title,summary,simplified_story,audience,language,tone,source,is_ai_generated,status,uncertainty_notes) VALUES ('record-tell-es-sultan','tell-es-sultan','Ancient Jericho / Tell es-Sultan','An oval mound north-west of present-day Jericho holding traces of human activity from about 10,500 BC, beside the perennial spring of ‘Ain es-Sultan.','An oval mound north-west of present-day Jericho holding traces of human activity from about 10,500 BC, beside the perennial spring of ‘Ain es-Sultan. The tell’s stratigraphy shows twenty-nine phases of occupation. By the 9th–8th millennium BC it was already a sizeable permanent settlement with a wall, a ditch and a tower. Middle Bronze Age remains reveal a large Canaanite city-state with innovative rampart fortifications. UNESCO inscribed the site on the World Heritage List in 2023.','general','en','neutral','content/ai-ready/tell-es-sultan-summary.md',FALSE,'published',ARRAY['This record contains source-checked factual summaries and credited, licensed photographs; each photograph shows its date and source. Local oral accounts and current access information have not been added. Coordinates, when available, are reference points, not entrances. This is a cultural reading journey; it does not establish a physical route, travel time, accessibility or permission to visit.']::text[]) ON CONFLICT DO NOTHING;
