INSERT INTO media (id,location_id,type,url,thumb_url,width,height,subject,subject_ar,description,description_ar,era,pair_role,credit,license,license_url,captured_at,source_url,sort_order) VALUES ('tell-es-sultan-04','tell-es-sultan','image','https://commons.wikimedia.org/wiki/Special:FilePath/Air_views_of_Palestine._Air_route_following_the_old_Jerusalem-Jericho_Road._Mound_of_ancient_Jericho._Looking_southward%2C_modern_Jericho_in_distance_LOC_matpc.22117.jpg?width=1600','https://commons.wikimedia.org/wiki/Special:FilePath/Air_views_of_Palestine._Air_route_following_the_old_Jerusalem-Jericho_Road._Mound_of_ancient_Jericho._Looking_southward%2C_modern_Jericho_in_distance_LOC_matpc.22117.jpg?width=600',4389,2932,'Tell es-Sultan from the air','تل السلطان من الجو','The mound of ancient Jericho from the air in 1931, looking south towards the modern town.','تلّ أريحا القديمة من الجو عام 1931، بالنظر جنوباً نحو البلدة الحديثة.','historical',NULL,'Matson Collection, Library of Congress','Public domain','https://creativecommons.org/publicdomain/mark/1.0/','1931','https://commons.wikimedia.org/wiki/File:Air_views_of_Palestine._Air_route_following_the_old_Jerusalem-Jericho_Road._Mound_of_ancient_Jericho._Looking_southward,_modern_Jericho_in_distance_LOC_matpc.22117.jpg',3) ON CONFLICT DO NOTHING;
INSERT INTO quiz_questions (id,location_id,question,options,answer_index,explanation,source_note,sort_order) VALUES ('palestine-quiz-tell-es-sultan','tell-es-sultan','How many phases of occupation does the stratigraphy of Tell es-Sultan show?',ARRAY['Three','Twenty-nine','One hundred']::text[],1,'An oval mound north-west of present-day Jericho holding traces of human activity from about 10,500 BC, beside the perennial spring of ‘Ain es-Sultan. The tell’s stratigraphy shows twenty-nine phases of occupation. By the 9th–8th millennium BC it was already a sizeable permanent settlement with a wall, a ditch and a tower. Middle Bronze Age remains reveal a large Canaanite city-state with innovative rampart fortifications. UNESCO inscribed the site on the World Heritage List in 2023. ','https://whc.unesco.org/en/list/1687/',0) ON CONFLICT DO NOTHING;
INSERT INTO locations (id,governorate_id,name,arabic_name,city,country,latitude,longitude,description,arabic_description,content_file,ai_summary_file,is_published,review_status,coordinate_status) VALUES ('hishams-palace','jericho','Hisham’s Palace / Khirbet al-Mafjar','قصر هشام / خربة المفجر','Jericho','Palestine',31.882294,35.459953,'An Umayyad winter retreat about 4 km north of Jericho, built between 724 and 743 AD and famous for its bath-hall mosaics and the Tree of Life.','منتجع شتوي أموي على بعد نحو 4 كم شمال أريحا، بُني بين عامي 724 و743م، ويشتهر بفسيفساء قاعة الحمّام ولوحة شجرة الحياة.','content/ai-ready/hishams-palace-summary.md','content/ai-ready/hishams-palace-summary.md',TRUE,'source_checked','unesco_tentative_list_reference') ON CONFLICT DO NOTHING;
