INSERT INTO stories (id,location_id,title,summary,simplified_story,audience,language,tone,source,is_ai_generated,status,uncertainty_notes) VALUES ('record-hishams-palace','hishams-palace','Hisham’s Palace / Khirbet al-Mafjar','An Umayyad winter retreat about 4 km north of Jericho, built between 724 and 743 AD and famous for its bath-hall mosaics and the Tree of Life.','An Umayyad winter retreat about 4 km north of Jericho, built between 724 and 743 AD and famous for its bath-hall mosaics and the Tree of Life. Inscriptions suggest it was built by Caliph Hisham bin Abd al-Malik and decorated by his heir al-Walid II; an earthquake destroyed it in 749 AD. The bath hall’s floor, about 30 by 30 metres, is made of 38 mosaic carpets — one of the largest early Islamic mosaic floors in the world. The first excavations, from 1935 to 1948, were directed by Dimitri Baramki.','general','en','neutral','content/ai-ready/hishams-palace-summary.md',FALSE,'published',ARRAY['This record contains source-checked factual summaries and credited, licensed photographs; each photograph shows its date and source. Local oral accounts and current access information have not been added. Coordinates, when available, are reference points, not entrances. This is a cultural reading journey; it does not establish a physical route, travel time, accessibility or permission to visit.']::text[]) ON CONFLICT DO NOTHING;
