INSERT INTO quiz_questions (id,location_id,question,options,answer_index,explanation,source_note,sort_order) VALUES ('palestine-quiz-hishams-palace','hishams-palace','How many mosaic carpets make up the floor of the bath hall?',ARRAY['8','38','380']::text[],1,'An Umayyad winter retreat about 4 km north of Jericho, built between 724 and 743 AD and famous for its bath-hall mosaics and the Tree of Life. Inscriptions suggest it was built by Caliph Hisham bin Abd al-Malik and decorated by his heir al-Walid II; an earthquake destroyed it in 749 AD. The bath hall’s floor, about 30 by 30 metres, is made of 38 mosaic carpets — one of the largest early Islamic mosaic floors in the world. The first excavations, from 1935 to 1948, were directed by Dimitri Baramki. ','https://whc.unesco.org/en/tentativelists/6546/',0) ON CONFLICT DO NOTHING;
INSERT INTO locations (id,governorate_id,name,arabic_name,city,country,latitude,longitude,description,arabic_description,content_file,ai_summary_file,is_published,review_status,coordinate_status) VALUES ('monastery-of-the-temptation','jericho','Monastery of the Temptation (Deir al-Quruntul)','دير قرنطل (دير التجربة)','Jericho','Palestine',31.874444,35.430278,'A Greek Orthodox monastery carved into the eastern cliffs of the Mount of Temptation, looking over Jericho and the Jordan Valley.','دير أرثوذكسي يوناني منحوت في المنحدرات الشرقية لجبل قرنطل (جبل التجربة)، يطلّ على أريحا ووادي الأردن.','content/ai-ready/monastery-of-the-temptation-summary.md','content/ai-ready/monastery-of-the-temptation-summary.md',TRUE,'source_checked','unesco_tentative_list_reference') ON CONFLICT DO NOTHING;
