INSERT INTO stories (id,location_id,title,summary,simplified_story,audience,language,tone,source,is_ai_generated,status,uncertainty_notes) VALUES ('record-monastery-of-the-temptation','monastery-of-the-temptation','Monastery of the Temptation (Deir al-Quruntul)','A Greek Orthodox monastery carved into the eastern cliffs of the Mount of Temptation, looking over Jericho and the Jordan Valley.','A Greek Orthodox monastery carved into the eastern cliffs of the Mount of Temptation, looking over Jericho and the Jordan Valley. A monastery was built in the 6th century over the cave associated with the Temptation, and the site is also identified with Chariton’s second foundation, the Douka monastery. About forty caves on the mountain’s eastern slopes served monks as sanctuaries. The present monastery was restored in 1892 and is overseen by the Greek Orthodox Patriarchate of Jerusalem.','general','en','neutral','content/ai-ready/monastery-of-the-temptation-summary.md',FALSE,'published',ARRAY['This record contains source-checked factual summaries and credited, licensed photographs; each photograph shows its date and source. Local oral accounts and current access information have not been added. Coordinates, when available, are reference points, not entrances. This is a cultural reading journey; it does not establish a physical route, travel time, accessibility or permission to visit.']::text[]) ON CONFLICT DO NOTHING;
