INSERT INTO media (id,location_id,type,url,thumb_url,width,height,subject,subject_ar,description,description_ar,era,pair_role,credit,license,license_url,captured_at,source_url,sort_order) VALUES ('monastery-of-the-temptation-04','monastery-of-the-temptation','image','https://commons.wikimedia.org/wiki/Special:FilePath/Gezicht_op_de_Berg_der_Verzoeking_bij_Jericho_Montagne_de_la_quarantaine_%28Palestine%29_%28titel_op_object%29_%28..%29_Montagne_de_la_quarantaine_%28Palestine%29_%28titel_op_object%29%2C_RP-F-F01089-AU.jpg?width=1600','https://commons.wikimedia.org/wiki/Special:FilePath/Gezicht_op_de_Berg_der_Verzoeking_bij_Jericho_Montagne_de_la_quarantaine_%28Palestine%29_%28titel_op_object%29_%28..%29_Montagne_de_la_quarantaine_%28Palestine%29_%28titel_op_object%29%2C_RP-F-F01089-AU.jpg?width=600',3918,3118,'Mount of Temptation','جبل قرنطل','The Mount of Temptation in a 19th-century photograph (about 1867–1895) held by the Rijksmuseum.','جبل قرنطل في صورة من القرن التاسع عشر (نحو 1867–1895) محفوظة في متحف رايكس.','historical',NULL,'Rijksmuseum','CC0','https://creativecommons.org/publicdomain/zero/1.0/','between 1867 and 1895','https://commons.wikimedia.org/wiki/File:Gezicht_op_de_Berg_der_Verzoeking_bij_Jericho_Montagne_de_la_quarantaine_(Palestine)_(titel_op_object)_(..)_Montagne_de_la_quarantaine_(Palestine)_(titel_op_object),_RP-F-F01089-AU.jpg',3) ON CONFLICT DO NOTHING;
INSERT INTO quiz_questions (id,location_id,question,options,answer_index,explanation,source_note,sort_order) VALUES ('palestine-quiz-monastery-of-the-temptation','monastery-of-the-temptation','In which year was the present Monastery of the Temptation restored?',ARRAY['1492','1892','1992']::text[],1,'A Greek Orthodox monastery carved into the eastern cliffs of the Mount of Temptation, looking over Jericho and the Jordan Valley. A monastery was built in the 6th century over the cave associated with the Temptation, and the site is also identified with Chariton’s second foundation, the Douka monastery. About forty caves on the mountain’s eastern slopes served monks as sanctuaries. The present monastery was restored in 1892 and is overseen by the Greek Orthodox Patriarchate of Jerusalem. According to Christian tradition, drawing on the Gospel of Luke, Jesus fasted and meditated here for forty days and nights before Satan tried to tempt him.','https://whc.unesco.org/en/tentativelists/6954/',0) ON CONFLICT DO NOTHING;
INSERT INTO locations (id,governorate_id,name,arabic_name,city,country,latitude,longitude,description,arabic_description,content_file,ai_summary_file,is_published,review_status,coordinate_status) VALUES ('church-of-the-nativity','bethlehem','Church of the Nativity and the Pilgrimage Route','كنيسة المهد ومسار الحجاج','Bethlehem','Palestine',31.704353,35.2075,'The place identified by Christian tradition since the 2nd century as the birthplace of Jesus, where the oldest Christian church in daily use stands among its convents at the end of the pilgrimage route.','المكان الذي يحدّده التقليد المسيحي منذ القرن الثاني مكاناً لميلاد السيد المسيح، وفيه أقدم كنيسة مسيحية ما زالت تُستخدم يومياً، تحيط بها الأديرة عند نهاية مسار الحجاج.','content/ai-ready/church-of-the-nativity-summary.md','content/ai-ready/church-of-the-nativity-summary.md',TRUE,'source_checked','unesco_property_reference') ON CONFLICT DO NOTHING;
