INSERT INTO stories (id,location_id,title,summary,simplified_story,audience,language,tone,source,is_ai_generated,status,uncertainty_notes) VALUES ('record-church-of-the-nativity','church-of-the-nativity','Church of the Nativity and the Pilgrimage Route','The place identified by Christian tradition since the 2nd century as the birthplace of Jesus, where the oldest Christian church in daily use stands among its convents at the end of the pilgrimage route.','The place identified by Christian tradition since the 2nd century as the birthplace of Jesus, where the oldest Christian church in daily use stands among its convents at the end of the pilgrimage route. A first church was completed here in 339 AD. The present church is essentially the 6th-century rebuilding of the time of Justinian; it keeps parts of the original 4th-century floor mosaics and has 12th-century additions. UNESCO inscribed the property in 2012, and it stayed on the List of World Heritage in Danger from 2012 to 2019. The Greek Orthodox Church, the Custody of the Holy Land and the Armenian Church share it under the Status Quo of the Holy Places.','general','en','neutral','content/ai-ready/church-of-the-nativity-summary.md',FALSE,'published',ARRAY['This record contains source-checked factual summaries and credited, licensed photographs; each photograph shows its date and source. Local oral accounts and current access information have not been added. Coordinates, when available, are reference points, not entrances. This is a cultural reading journey; it does not establish a physical route, travel time, accessibility or permission to visit.']::text[]) ON CONFLICT DO NOTHING;
