INSERT INTO timeline_events (id,location_id,period_label,description,sort_year,sort_order,is_tradition,source_file) VALUES ('palestine-timeline-church-of-the-nativity-1','church-of-the-nativity','6th century (533 AD)','The church is rebuilt after a fire; this Justinian-era building is essentially the church standing today.',533,1,FALSE,'content/ai-ready/church-of-the-nativity-summary.md') ON CONFLICT DO NOTHING;
INSERT INTO timeline_events (id,location_id,period_label,description,sort_year,sort_order,is_tradition,source_file) VALUES ('palestine-timeline-church-of-the-nativity-2','church-of-the-nativity','12th century','Crusader-period additions, including the paintings on the columns, mark a new upsurge in pilgrimage.',1100,2,FALSE,'content/ai-ready/church-of-the-nativity-summary.md') ON CONFLICT DO NOTHING;
INSERT INTO timeline_events (id,location_id,period_label,description,sort_year,sort_order,is_tradition,source_file) VALUES ('palestine-timeline-church-of-the-nativity-3','church-of-the-nativity','1878','The Status Quo of the Holy Places, under which the three churches share the site, is set by the Treaty of Berlin.',1878,3,FALSE,'content/ai-ready/church-of-the-nativity-summary.md') ON CONFLICT DO NOTHING;
