INSERT INTO media (id,location_id,type,url,thumb_url,width,height,subject,subject_ar,description,description_ar,era,pair_role,credit,license,license_url,captured_at,source_url,sort_order) VALUES ('church-of-the-nativity-03','church-of-the-nativity','image','https://commons.wikimedia.org/wiki/Special:FilePath/%D8%B9%D8%B1%D8%A7%D9%82%D8%A9_%D8%A7%D9%84%D8%AA%D9%81%D8%A7%D8%B5%D9%8A%D9%84.jpg?width=1600','https://commons.wikimedia.org/wiki/Special:FilePath/%D8%B9%D8%B1%D8%A7%D9%82%D8%A9_%D8%A7%D9%84%D8%AA%D9%81%D8%A7%D8%B5%D9%8A%D9%84.jpg?width=600',6960,4640,'Basilica column capital','تاج عمود في البازيليكا','A carved Corinthian capital on one of the historic columns inside the church.','تاج كورنثي منحوت بدقة على أحد الأعمدة التاريخية داخل الكنيسة.','modern',NULL,'Shima'' Zaareer','CC BY-SA 4.0','https://creativecommons.org/licenses/by-sa/4.0','2025-12-22','https://commons.wikimedia.org/wiki/File:%D8%B9%D8%B1%D8%A7%D9%82%D8%A9_%D8%A7%D9%84%D8%AA%D9%81%D8%A7%D8%B5%D9%8A%D9%84.jpg',2) ON CONFLICT DO NOTHING;
INSERT INTO media (id,location_id,type,url,thumb_url,width,height,subject,subject_ar,description,description_ar,era,pair_role,credit,license,license_url,captured_at,source_url,sort_order) VALUES ('church-of-the-nativity-04','church-of-the-nativity','image','https://commons.wikimedia.org/wiki/Special:FilePath/Bethlehem_and_surroundings._Bethlehem%2C_nave_of_the_Basilica_%28Church_of_the_Nativity%29._Light-shafts_encircling_the_ancient_pillars_LOC_matpc.02619.jpg?width=1600','https://commons.wikimedia.org/wiki/Special:FilePath/Bethlehem_and_surroundings._Bethlehem%2C_nave_of_the_Basilica_%28Church_of_the_Nativity%29._Light-shafts_encircling_the_ancient_pillars_LOC_matpc.02619.jpg?width=600',6417,4744,'Nave of the basilica','صحن البازيليكا','Shafts of light between the rows of columns in the basilica’s nave, photographed in 1920.','أشعة الضوء تتسلل بين صفوف الأعمدة في صحن البازيليكا، في صورة التُقطت عام 1920.','historical',NULL,'Matson Collection, Library of Congress','Public domain','https://creativecommons.org/publicdomain/mark/1.0/','1920','https://commons.wikimedia.org/wiki/File:Bethlehem_and_surroundings._Bethlehem,_nave_of_the_Basilica_(Church_of_the_Nativity)._Light-shafts_encircling_the_ancient_pillars_LOC_matpc.02619.jpg',3) ON CONFLICT DO NOTHING;
INSERT INTO quiz_questions (id,location_id,question,options,answer_index,explanation,source_note,sort_order) VALUES ('palestine-quiz-church-of-the-nativity','church-of-the-nativity','In which year was the first church on the site completed?',ARRAY['339 AD','1099 AD','1878 AD']::text[],0,'The place identified by Christian tradition since the 2nd century as the birthplace of Jesus, where the oldest Christian church in daily use stands among its convents at the end of the pilgrimage route. A first church was completed here in 339 AD. The present church is essentially the 6th-century rebuilding of the time of Justinian; it keeps parts of the original 4th-century floor mosaics and has 12th-century additions. UNESCO inscribed the property in 2012, and it stayed on the List of World Heritage in Danger from 2012 to 2019. The Greek Orthodox Church, the Custody of the Holy Land and the Armenian Church share it under the Status Quo of the Holy Places. According to Christian tradition, a cave beneath the church is where Jesus was born; belief in this place is recorded from at least the 2nd century AD.','https://whc.unesco.org/en/list/1433/',0) ON CONFLICT DO NOTHING;
INSERT INTO locations (id,governorate_id,name,arabic_name,city,country,latitude,longitude,description,arabic_description,content_file,ai_summary_file,is_published,review_status,coordinate_status) VALUES ('battir','bethlehem','Battir: Land of Olives and Vines','بتير: أرض الزيتون والكرمة','Battir','Palestine',31.724722,35.136667,'A cultural landscape of farmed valleys south-west of Jerusalem, with dry-stone terraces, irrigation channels and a water-sharing system still kept by the families of Battir.','مشهد ثقافي من الأودية الزراعية جنوب غرب القدس، فيه مدرّجات حجرية جافة وقنوات ري ونظام لتقاسم الماء ما زالت عائلات بتير تحافظ عليه.','content/ai-ready/battir-summary.md','content/ai-ready/battir-summary.md',TRUE,'source_checked','village_centre_reference') ON CONFLICT DO NOTHING;
