INSERT INTO stories (id,location_id,title,summary,simplified_story,audience,language,tone,source,is_ai_generated,status,uncertainty_notes) VALUES ('record-battir','battir','Battir: Land of Olives and Vines','A cultural landscape of farmed valleys south-west of Jerusalem, with dry-stone terraces, irrigation channels and a water-sharing system still kept by the families of Battir.','A cultural landscape of farmed valleys south-west of Jerusalem, with dry-stone terraces, irrigation channels and a water-sharing system still kept by the families of Battir. UNESCO inscribed the landscape in 2014 as “Palestine: Land of Olives and Vines – Cultural Landscape of Southern Jerusalem, Battir” and placed it on the List of World Heritage in Danger the same year. The terraces are fed by a network of channels from underground sources, and the water is shared between the village families in a time-managed rotation. UNESCO’s statement warns that building a separation barrier through the valley would severely damage the terraces and the landscape.','general','en','neutral','content/ai-ready/battir-summary.md',FALSE,'published',ARRAY['The map point marks the village of Battir, not the boundary of the serial property. Current access and site condition are not asserted.']::text[]) ON CONFLICT DO NOTHING;
INSERT INTO timeline_events (id,location_id,period_label,description,sort_year,sort_order,is_tradition,source_file) VALUES ('palestine-timeline-battir-0','battir','2014','Inscribed on the World Heritage List and, the same year, on the List of World Heritage in Danger.',2014,0,FALSE,'content/ai-ready/battir-summary.md') ON CONFLICT DO NOTHING;
