INSERT INTO quiz_questions (id,location_id,question,options,answer_index,explanation,source_note,sort_order) VALUES ('palestine-quiz-battir','battir','How do the families of Battir share their irrigation water?',ARRAY['By a time-managed rotation','By buying it from a city network','They do not irrigate their terraces']::text[],0,'A cultural landscape of farmed valleys south-west of Jerusalem, with dry-stone terraces, irrigation channels and a water-sharing system still kept by the families of Battir. UNESCO inscribed the landscape in 2014 as “Palestine: Land of Olives and Vines – Cultural Landscape of Southern Jerusalem, Battir” and placed it on the List of World Heritage in Danger the same year. The terraces are fed by a network of channels from underground sources, and the water is shared between the village families in a time-managed rotation. UNESCO’s statement warns that building a separation barrier through the valley would severely damage the terraces and the landscape. ','https://whc.unesco.org/en/list/1492/',0) ON CONFLICT DO NOTHING;
INSERT INTO locations (id,governorate_id,name,arabic_name,city,country,latitude,longitude,description,arabic_description,content_file,ai_summary_file,is_published,review_status,coordinate_status) VALUES ('mar-saba-monastery','bethlehem','Mar Saba Monastery','دير مار سابا','Wadi al-Nar (Kidron Valley)','Palestine',31.704722,35.331111,'A Greek Orthodox monastery built into the cliffs of the Kidron Valley, founded in 483 AD by Saint Sabbas and inhabited almost continuously ever since.','دير أرثوذكسي يوناني مبنيّ في منحدرات وادي النار (قدرون)، أسّسه القديس سابا عام 483م، وسكنه الرهبان بشكل شبه متواصل منذ ذلك الحين.','content/ai-ready/mar-saba-monastery-summary.md','content/ai-ready/mar-saba-monastery-summary.md',TRUE,'source_checked','unesco_tentative_list_reference') ON CONFLICT DO NOTHING;
