INSERT INTO stories (id,location_id,title,summary,simplified_story,audience,language,tone,source,is_ai_generated,status,uncertainty_notes) VALUES ('record-mar-saba-monastery','mar-saba-monastery','Mar Saba Monastery','A Greek Orthodox monastery built into the cliffs of the Kidron Valley, founded in 483 AD by Saint Sabbas and inhabited almost continuously ever since.','A Greek Orthodox monastery built into the cliffs of the Kidron Valley, founded in 483 AD by Saint Sabbas and inhabited almost continuously ever since. Mar Saba began as a line of hermit caves along more than two kilometres of cliffs, and many of its chapels and cells are carved into the limestone. St John of Damascus lived here in the 8th century. A severe earthquake damaged the monastery in 1834, and it was rebuilt largely with Russian support. It is overseen by the Greek Orthodox Patriarchate of Jerusalem; women are not permitted inside the monastery itself.','general','en','neutral','content/ai-ready/mar-saba-monastery-summary.md',FALSE,'published',ARRAY['This record contains source-checked factual summaries and credited, licensed photographs; each photograph shows its date and source. Local oral accounts and current access information have not been added. Coordinates, when available, are reference points, not entrances. This is a cultural reading journey; it does not establish a physical route, travel time, accessibility or permission to visit.']::text[]) ON CONFLICT DO NOTHING;
