INSERT INTO timeline_events (id,location_id,period_label,description,sort_year,sort_order,is_tradition,source_file) VALUES ('palestine-timeline-mar-saba-monastery-1','mar-saba-monastery','491 AD','The Church of Theoktistos, later dedicated to St Nicholas, is built.',491,1,FALSE,'content/ai-ready/mar-saba-monastery-summary.md') ON CONFLICT DO NOTHING;
