INSERT INTO quiz_questions (id,location_id,question,options,answer_index,explanation,source_note,sort_order) VALUES ('palestine-quiz-mar-saba-monastery','mar-saba-monastery','Who founded Mar Saba Monastery in 483 AD?',ARRAY['Saint Sabbas','Saint Hilarion','Emperor Justinian']::text[],0,'A Greek Orthodox monastery built into the cliffs of the Kidron Valley, founded in 483 AD by Saint Sabbas and inhabited almost continuously ever since. Mar Saba began as a line of hermit caves along more than two kilometres of cliffs, and many of its chapels and cells are carved into the limestone. St John of Damascus lived here in the 8th century. A severe earthquake damaged the monastery in 1834, and it was rebuilt largely with Russian support. It is overseen by the Greek Orthodox Patriarchate of Jerusalem; women are not permitted inside the monastery itself. ','https://whc.unesco.org/en/tentativelists/6954/',0) ON CONFLICT DO NOTHING;
