INSERT INTO quiz_questions (id,location_id,question,options,answer_index,explanation,source_note,sort_order) VALUES ('palestine-quiz-ibrahimi-mosque','ibrahimi-mosque','How should the association with Ibrahim / Abraham be understood here?',ARRAY['As religious tradition','As a verified excavation result','As a transport instruction']::text[],0,'A sacred architectural complex at the heart of Hebron''s old town. The Hebron Rehabilitation Committee documents successive Byzantine, Islamic and Crusader architectural layers. Religious tradition associates the site with Ibrahim / Abraham and his family; this is presented as belief, not archaeological proof.','https://www.hebronrc.ps/xindex.php/en/node/275',0) ON CONFLICT DO NOTHING;
