INSERT INTO locations (id,governorate_id,name,arabic_name,city,country,latitude,longitude,description,arabic_description,content_file,ai_summary_file,is_published,review_status,coordinate_status) VALUES ('saint-hilarion-monastery','gaza','Saint Hilarion Monastery / Tell Umm Amer','دير القديس هيلاريون / تل أم عامر','Nuseirat','Palestine',31.447306,34.366361,'The ruins of one of the earliest monastic sites in the Middle East, founded in the 4th century by Saint Hilarion on the coastal dunes of Nuseirat.','أطلال واحد من أقدم المواقع الرهبانية في الشرق الأوسط، أسّسه القديس هيلاريون في القرن الرابع على الكثبان الساحلية في النصيرات.','content/ai-ready/saint-hilarion-monastery-summary.md','content/ai-ready/saint-hilarion-monastery-summary.md',TRUE,'source_checked','unesco_property_reference') ON CONFLICT DO NOTHING;
