INSERT INTO stories (id,location_id,title,summary,simplified_story,audience,language,tone,source,is_ai_generated,status,uncertainty_notes) VALUES ('record-saint-hilarion-monastery','saint-hilarion-monastery','Saint Hilarion Monastery / Tell Umm Amer','The ruins of one of the earliest monastic sites in the Middle East, founded in the 4th century by Saint Hilarion on the coastal dunes of Nuseirat.','The ruins of one of the earliest monastic sites in the Middle East, founded in the 4th century by Saint Hilarion on the coastal dunes of Nuseirat. It was the first monastic community in the Holy Land, growing from a mud-brick hermitage into a large church complex. Its remains include three superimposed churches with elaborate mosaic floors, crypts, cells, a refectory, a water system and baths within a pilgrim hostel. UNESCO inscribed it on the World Heritage List in 2024 and, the same year, on the List of World Heritage in Danger.','general','en','neutral','content/ai-ready/saint-hilarion-monastery-summary.md',FALSE,'published',ARRAY['Current site condition and access are not asserted. The record describes the documented heritage; each photograph shows the date it was taken.']::text[]) ON CONFLICT DO NOTHING;
