INSERT INTO quiz_questions (id,location_id,question,options,answer_index,explanation,source_note,sort_order) VALUES ('palestine-quiz-saint-hilarion-monastery','saint-hilarion-monastery','Where does Saint Hilarion Monastery stand?',ARRAY['On the coastal dunes of Nuseirat','In the Kidron Valley','On Mount Gerizim']::text[],0,'The ruins of one of the earliest monastic sites in the Middle East, founded in the 4th century by Saint Hilarion on the coastal dunes of Nuseirat. It was the first monastic community in the Holy Land, growing from a mud-brick hermitage into a large church complex. Its remains include three superimposed churches with elaborate mosaic floors, crypts, cells, a refectory, a water system and baths within a pilgrim hostel. UNESCO inscribed it on the World Heritage List in 2024 and, the same year, on the List of World Heritage in Danger. ','https://whc.unesco.org/en/list/1749/',0) ON CONFLICT DO NOTHING;
INSERT INTO locations (id,governorate_id,name,arabic_name,city,country,latitude,longitude,description,arabic_description,content_file,ai_summary_file,is_published,review_status,coordinate_status) VALUES ('anthedon-harbour','gaza','Anthedon Harbour','ميناء الأنثيدون (البلاخية)','Gaza','Palestine',NULL,NULL,'The first known seaport of Gaza, called Tida or Blakhiyeh in Islamic literature, inhabited from 800 BC to 1100 AD.','أول ميناء معروف لغزة، ويُسمّى في المصادر الإسلامية «تيدا» أو «البلاخية»، وقد سُكن من عام 800 ق.م حتى 1100م.','content/ai-ready/anthedon-harbour-summary.md','content/ai-ready/anthedon-harbour-summary.md',TRUE,'source_checked','pending_verification') ON CONFLICT DO NOTHING;
