INSERT INTO stories (id,location_id,title,summary,simplified_story,audience,language,tone,source,is_ai_generated,status,uncertainty_notes) VALUES ('record-anthedon-harbour','anthedon-harbour','Anthedon Harbour','The first known seaport of Gaza, called Tida or Blakhiyeh in Islamic literature, inhabited from 800 BC to 1100 AD.','The first known seaport of Gaza, called Tida or Blakhiyeh in Islamic literature, inhabited from 800 BC to 1100 AD. The harbour saw Neo-Assyrian, Babylonian, Persian, Greek, Roman, Byzantine and early Islamic rule. Excavations uncovered a Roman temple, villas, mosaic floors, warehouses, a 65-metre mud-brick wall and massive earthen walls 8 metres high and 6 metres thick. One kilometre to the south lay Maiumas, the ancient harbour of Gaza.','general','en','neutral','content/ai-ready/anthedon-harbour-summary.md',FALSE,'published',ARRAY['UNESCO’s entry notes that the site of ancient Anthedon has not been precisely identified, and its listed coordinates do not point to Gaza, so no map marker is shown. Current site condition and access are not asserted. The record describes the documented heritage; each photograph shows the date it was taken.']::text[]) ON CONFLICT DO NOTHING;
INSERT INTO timeline_events (id,location_id,period_label,description,sort_year,sort_order,is_tradition,source_file) VALUES ('palestine-timeline-anthedon-harbour-0','anthedon-harbour','800 BC','The earliest documented habitation of the harbour city.',-800,0,FALSE,'content/ai-ready/anthedon-harbour-summary.md') ON CONFLICT DO NOTHING;
INSERT INTO timeline_events (id,location_id,period_label,description,sort_year,sort_order,is_tradition,source_file) VALUES ('palestine-timeline-anthedon-harbour-1','anthedon-harbour','1100 AD','The end of the documented habitation.',1100,1,FALSE,'content/ai-ready/anthedon-harbour-summary.md') ON CONFLICT DO NOTHING;
