INSERT INTO media (id,location_id,type,url,thumb_url,width,height,subject,subject_ar,description,description_ar,era,pair_role,credit,license,license_url,captured_at,source_url,sort_order) VALUES ('anthedon-harbour-01','anthedon-harbour','image','https://commons.wikimedia.org/wiki/Special:FilePath/Tr%C3%A9sors_sauv%C3%A9s_de_Gaza_IMG_9510.jpg?width=1600','https://commons.wikimedia.org/wiki/Special:FilePath/Tr%C3%A9sors_sauv%C3%A9s_de_Gaza_IMG_9510.jpg?width=600',4640,6960,'Greek head from Anthedon','رأس يوناني من الأنثيدون','A Greek stone head in Cypriot style found at Anthedon, shown in the 2025 exhibition “Trésors sauvés de Gaza” at the Institut du monde arabe, Paris.','رأس حجري يوناني على الطراز القبرصي عُثر عليه في الأنثيدون، عُرض في معرض «كنوز غزة المُنقَذة» في معهد العالم العربي في باريس عام 2025.','modern','cover','David.Monniaux','CC BY-SA 4.0','https://creativecommons.org/licenses/by-sa/4.0','2025-10-21','https://commons.wikimedia.org/wiki/File:Tr%C3%A9sors_sauv%C3%A9s_de_Gaza_IMG_9510.jpg',0) ON CONFLICT DO NOTHING;
INSERT INTO media (id,location_id,type,url,thumb_url,width,height,subject,subject_ar,description,description_ar,era,pair_role,credit,license,license_url,captured_at,source_url,sort_order) VALUES ('anthedon-harbour-02','anthedon-harbour','image','https://commons.wikimedia.org/wiki/Special:FilePath/Tr%C3%A9sors_sauv%C3%A9s_de_Gaza_IMG_9491.jpg?width=1600','https://commons.wikimedia.org/wiki/Special:FilePath/Tr%C3%A9sors_sauv%C3%A9s_de_Gaza_IMG_9491.jpg?width=600',4640,6960,'Glass flask from Anthedon','قارورة زجاجية من الأنثيدون','A glass flask shaped like a human head, found at Anthedon and shown in the same 2025 exhibition.','قارورة زجاجية على شكل رأس إنسان عُثر عليها في الأنثيدون، وعُرضت في المعرض نفسه عام 2025.','modern',NULL,'David.Monniaux','CC BY-SA 4.0','https://creativecommons.org/licenses/by-sa/4.0','2025-10-21','https://commons.wikimedia.org/wiki/File:Tr%C3%A9sors_sauv%C3%A9s_de_Gaza_IMG_9491.jpg',1) ON CONFLICT DO NOTHING;
INSERT INTO quiz_questions (id,location_id,question,options,answer_index,explanation,source_note,sort_order) VALUES ('palestine-quiz-anthedon-harbour','anthedon-harbour','What was Anthedon?',ARRAY['A desert monastery','The first known seaport of Gaza','A Roman theatre in Nablus']::text[],1,'The first known seaport of Gaza, called Tida or Blakhiyeh in Islamic literature, inhabited from 800 BC to 1100 AD. The harbour saw Neo-Assyrian, Babylonian, Persian, Greek, Roman, Byzantine and early Islamic rule. Excavations uncovered a Roman temple, villas, mosaic floors, warehouses, a 65-metre mud-brick wall and massive earthen walls 8 metres high and 6 metres thick. One kilometre to the south lay Maiumas, the ancient harbour of Gaza. ','https://whc.unesco.org/en/tentativelists/5719/',0) ON CONFLICT DO NOTHING;
